class IdentityDocumentsCtrl {
	constructor(container, userId, readOnlyAll) {
		this.container = container;
		this.userId = userId;
		this.identityDocumentTmpl = "";
		this.identityDocumentInfoTmpl = "";
		this.identityDocumentTypes = "";
		this.identityDocumentTextFieldTmpl = "";
		this.readOnlyAll = readOnlyAll;

		this.loader = new IdentityDocumentsLoader();

		const loadTemplate = (url, setFunc) => {
			return $.ajax({
				url: url,
				cache: true,
				success: (data) => setFunc(data.replace(/(?:\r\n|\r|\n)/g, ""))
			});
		}

		const queries = [
			loadTemplate("/static/dist/pages/users/templates/IdentityDocumentsTemplate.html", 
				(html) => this.identityDocumentTmpl = html),
			loadTemplate("/static/dist/pages/users/templates/IdentityDocumentInfoTemplate.html",
				(html) => this.identityDocumentInfoTmpl = html),
			loadTemplate("/static/dist/pages/users/templates/IdentityDocumentTextFieldTemplate.html",
				(html) => this.identityDocumentTextFieldTmpl = html),
			loadTemplate("/static/dist/pages/users/templates/IdentityDocumentDateFieldTemplate.html",
				(html) => this.identityDocumentDateFieldTmpl = html)
		];

		Handlebars.registerHelper("DateOnly2strF", (dateParam) => dateParam ? dateUtils.date2strfrm(new Date(dateParam), `dd${String.fromCharCode(1)}mm${String.fromCharCode(1)}yyyy${String.fromCharCode(1)}.`) : null);
		Handlebars.registerHelper("CheckField", (fields, field, opts) => field & fields ? opts.fn(this) : opts.inverse(this));
		Handlebars.registerHelper("ifEqual", (nParam1, nParam2, opts) => (nParam1 === nParam2) ? opts.fn(this) : opts.inverse(this));

		this.container.on("click", "button[name=add-button]", () => { this.addIdentityDocument() });
		this.container.on("click", "button[name=edit-button]",
			(evt) => {
				const documentId = parseInt($(evt.currentTarget).data("docid"));
				this.editIdentityDocument(documentId);
			});
		this.container.on("click", "button[name=remove-button]",
			(evt) => {
				const documentId = parseInt($(evt.currentTarget).data("docid"));
				this.delIdentityDocument(documentId);
			});

		extDeferred.when(queries).then(() => {
			Handlebars.registerPartial("identityDocumentInfoTmpl", this.identityDocumentInfoTmpl);
			Handlebars.registerPartial("identityDocumentTextFieldTmpl", this.identityDocumentTextFieldTmpl);
			Handlebars.registerPartial("identityDocumentDateFieldTmpl", this.identityDocumentDateFieldTmpl);

			$.validator.messages.required = language.Generic.Common.kEmptyFieldError;

			$.validator.addMethod("pattern"
				, (value, element, opts) => {
					const regExp = new RegExp(opts.regex);
					if (!value && opts.optional) {
						return true;
					}
					return regExp.test(value);
				}
				, (opts) => opts.errorMessage);

			$.validator.addMethod("aboveOrEqualDate",
				(value, element, opts) => {
					const otherValue = opts.container.find(opts.element).val();
					if (!otherValue || opts.str2dt(value) >= opts.str2dt(otherValue)) {
						return true;
					}
					return false;
				},
				(opts) => opts.errorMessage);

			$.validator.addMethod("belowOrEqualDate",
				(value, element, opts) => {
					const otherValue = opts.container.find(opts.element).val();
					if (!otherValue || opts.str2dt(value) <= opts.str2dt(otherValue)) {
						return true;
					}
					return false;
				},
				(opts) => opts.errorMessage);

			this.template = Handlebars.compile(this.identityDocumentTmpl);
			this.infoTemplate = Handlebars.compile(this.identityDocumentInfoTmpl);
			//this.showIdentityDocuments();
		});
	}

	//отображение ошибки
	displayError(text) {
		this.container.html(`<div class="alert alert-danger">${text || language.Generic.Common.kUnexpErr}<div>`);
	}

	//отображение документов
	showIdentityDocuments() {
		//загрузка типов и документов и их отображение
		const errHandler = (response) => {
			const errorText = response && response.responseJSON && response.responseJSON.message
				? response.responseJSON.message
				: response && response.responseText ? response.responseText : language.Generic.Common.kUnexpErr;
			this.displayError(errorText);
		};

		this.loader.checkAccessIdentityDocuments(this.userId)
			.fail(errHandler)
			.then((check) => {
				if (check) {
					this.loader.getIdentityDocuments(this.userId)
						.fail(errHandler)
						.then((response) => {
							const html = this.template({
								identityDocuments: response,
								language: language,
								readonly: true,
								readOnlyAll: this.readOnlyAll
							});
							this.container.html(html);
						});
				} else {
					this.displayError("Доступ к данным закрыт");
				}
			});

	}

	//обновление данных по документу
	_refreshIdentityDocument(identityDocument) {
		const model = $.extend({}, identityDocument, { language: language, readonly: true});
		const html = this.infoTemplate(model);
		$(`#identity-document-${identityDocument.id}`).html(html);
	}

	_bindDocumentDataFromModal(container) {
		const documentData = {
			docType: container.find(`[name=documentType]`).val(),
			number: container.find(`[name=number]`).val(),
			series: container.find(`[name=series]`).val(),
			issuer: container.find(`[name=issuer]`).val(),
			otherDocName: container.find(`[name=otherDocName]`).val(),
			issuerCode: container.find(`[name=issuerCode]`).val(),
			actNumber: container.find(`[name=actNumber]`).val(),
			expireDate: container.find(`[name=expireDate]`).val() ? dateUtils.str2date(container.find(`[name=expireDate]`).val()) : null,
			issueDate: container.find(`[name=issueDate]`).val() ? dateUtils.str2date(container.find(`[name=issueDate]`).val()) : null
		};
		return documentData;
	}

	_showFields(container) {
		const str2Dt = (strDate) => new Date(strDate.substr(6, 4), strDate.substr(3, 2), strDate.substr(0, 2));
		const docTypeId = container.find("[name=documentType]").val();

		const identityDocumentType = _.findWhere(this.identityDocumentTypes, { id: docTypeId });

		if (!identityDocumentType) {
			throw new "Неизвестный тип документа уд. личность " + docTypeId;
		}

		const identityDocumentFields = identityDocumentType.identityDocumentFields;
		const fieldValidationOptions = _.indexBy(identityDocumentType.fieldValidationOptions, "fieldId");

		const setValidationAttrs = function (fieldId, fieldName) {
			const fieldRow = container.find(`div.field-row-${fieldName}`);
			const field = container.find(`input.field-input-${fieldName}`);

			if (!field.length) {
				return;
			}

			if (identityDocumentFields & fieldId) {
				//если поле присутствует у документа
				const validationOptions = fieldValidationOptions[fieldId];
				if (validationOptions) {
					const validationRule = {
						required: validationOptions.required,
						pattern: {
							regex: validationOptions.regex,
							optional: !validationOptions.required,
							errorMessage: validationOptions.errorMessage
						}
					};
					field.rules("add", validationRule);
				} else {
					//без валидации
					field.rules("remove");
				}
				fieldRow.show();
			} else {
				//отсутствует
				fieldRow.hide();
				field.rules("remove");
			};
			if (fieldId === 64 && identityDocumentFields & 32 && identityDocumentFields & 64) {
				const validationAboveDateRule = {
					aboveOrEqualDate: {
						container: container,
						element: "input.field-input-issueDate",
						errorMessage: "Дата окончания действия документа должна быть больше или равна, чем дата выдачи документа",
						str2dt: str2Dt
					}
				};
				field.rules("add", validationAboveDateRule);
			}
			if (fieldId === 32 && identityDocumentFields & 32 && identityDocumentFields & 64) {
				const validationBelowDateRule = {
					belowOrEqualDate: {
						container: container,
						element: "input.field-input-expireDate",
						errorMessage: "Дата выдачи документа должна быть меньше или равна дате окончания действия документа",
						str2dt: str2Dt
					}
				};
				field.rules("add", validationBelowDateRule);
			}
		};

		setValidationAttrs(1, "series");
		setValidationAttrs(2, "number");
		setValidationAttrs(4, "actNumber");
		setValidationAttrs(8, "issuer");
		setValidationAttrs(16, "issuerCode");
		setValidationAttrs(32, "issueDate");
		setValidationAttrs(64, "expireDate");
		setValidationAttrs(128, "otherDocName");
	}

	_preselectDocType(docTypeControl) {
		const types = ["RfPassport", "BirthCertificate"];

		for (let ind in types) {
			let preType = types[ind];
			if (!docTypeControl.find(`option[value=${preType}]`).length) {
				continue;
			}
			docTypeControl.val(preType);
			return;
		}
	}

	///редактировать документ
	editIdentityDocument(idIdentityDocument) {

		this.loader.getDocumentType(this.userId, idIdentityDocument)
			.then((response => {
				this.identityDocumentTypes = [response];
				this.loader.getDocumentInfo(this.userId, idIdentityDocument)
					.then((response) => {
						const model = $.extend({},
							response,
							{
								language: language,
								readonly: false,
								editMode: true,
								editFlag: true
							});

						const html = this.infoTemplate(model);
						let editForm = null;

						$.show.dialog({
							size: BootstrapDialog.SIZE_WIDE,
							title: `${language.Generic.Common.kEdit} ${language.Generic.Common.kIdentityDocument.toLowerCase()}`,
							message: html,
							onshown: (dialog) => {
								dateInput.initDateInputs(new Date(1900, 0, 1), new Date().addYears(50), null, { format: "dd.mm.yyyy" });
								editForm = dialog.$modalBody.find("form");
								editForm.validate();

								this._showFields(dialog.$modalBody);
							},
							buttons: [
								{
									label: language.Generic.Buttons.kSave,
									cssClass: "btn-primary",
									action: (dialog) => {
										if (!editForm.valid()) {
											alert(language.Generic.Common.kValidationError);
											return;
										}

										const documentData = this._bindDocumentDataFromModal(dialog.$modalBody);

										this.loader.saveDocumentInfo(this.userId, idIdentityDocument, documentData)
											.then((identityDocument) => {
												dialog.successClose();
												this._refreshIdentityDocument(identityDocument);
											});
									}
								}
							]
						});
					});
			}));
	}

	//добавить документ
	addIdentityDocument() {
		this.loader.getDocumentTypesForUser(this.userId)
			.then(response => {
				if (!response || response.length === 0) {
					alert(language.Generic.Common.kNotAvailableIdentityDocumentTypes);
					return;
				}

				this.identityDocumentTypes = response;
				const html = this.infoTemplate({
					language: language,
					readonly: false,
					addFlag: true,
					editMode: true,
					identityDocumentTypes: this.identityDocumentTypes,
					docTypeFields: 255
				});

				let editForm = null;

				const dialog = $.show.dialog({
					size: BootstrapDialog.SIZE_WIDE,
					title: `${language.Generic.Common.kAdd} ${language.Generic.Common.kIdentityDocument.toLowerCase()}`,
					message: html,
					deferredOpen: true,
					onshown: (dialog) => {
						const dateInputs = dialog.$modalBody.find(".input-group.date");
						dateInput.initDateInput(dateInputs, new Date(1900, 0, 1), new Date().addYears(50), null, { format: "dd.mm.yyyy" });
					},
					buttons: [
					{
						label: language.Generic.Buttons.kAdd,
						cssClass: "btn-primary",
						action: (dialog) => {
							if (!editForm.valid()) {
								alert(language.Generic.Common.kValidationError);
								return;
							}

							const documentData = this._bindDocumentDataFromModal(dialog.$modalBody);
							this.loader.addDocument(this.userId, documentData)
								.then(() => {
									dialog.successClose();
									this.showIdentityDocuments();
								});
						}
					}]
				});

				dialog.realize();

				let dialogBody = dialog.getModalBody();

				const docTypeControl = dialogBody.find("[name=documentType]");
				docTypeControl.change(() => this._showFields(dialogBody));

				editForm = dialogBody.find("form");
				editForm.validate();

				this._preselectDocType(docTypeControl);
				this._showFields(dialogBody);
			
				dialog.open();
			});
	}

	//удалить документ
	delIdentityDocument(idIdentityDocument) {
		$.show.confirmation(`${language.Generic.Common.kRemove} ${language.Generic.Common.kIdentityDocument.toLowerCase()}?`)
			.then(() => { return this.loader.deleteDocument(this.userId, idIdentityDocument) })
			.then(() => { this.showIdentityDocuments() });
	}
}

class IdentityDocumentsLoader {

	getIdentityDocuments(userId) {
		return jsSubmit({
			action: `/webapi/users/${userId}/info/identityDocuments`,
			method: "GET",
			auth: true,
			nocache: true,
			showProcessing: false,
			defaultErrorHandling: false
		});
	}

	checkAccessIdentityDocuments(userId) {
		return jsSubmit({
			action: `/webapi/users/${userId}/info/identityDocuments/checkAccess`,
			method: "GET",
			auth: true,
			nocache: true,
			showProcessing: false,
			defaultErrorHandling: false
		});
	}

	getDocumentInfo(userId, docId) {
		return jsSubmit({
			action: `/webapi/users/${userId}/info/identityDocuments/${docId}`,
			method: "GET",
			auth: true,
			nocache: true,
			showProcessing: true,
			defaultErrorHandling: true
		});
	}

	saveDocumentInfo(userId, docId, documentData) {
		return jsSubmit({
			contentType: "application/json",
			action: `/webapi/users/${userId}/info/identityDocuments/${docId}`,
			data: documentData,
			method: "POST",
			auth: true,
			showProcessing: true,
			defaultErrorHandling: true
		});
	}

	addDocument(userId, documentData) {
		return jsSubmit({
			contentType: "application/json",
			action: `/webapi/users/${userId}/info/identityDocuments`,
			data: documentData,
			method: "PUT",
			auth: true,
			showProcessing: true,
			defaultErrorHandling: true
		});
	}

	getDocumentTypesForUser(userId) {
		return jsSubmit({
			action: `/webapi/users/${userId}/info/identityDocuments/identityDocumentTypes`,
			method: "GET",
			auth: true,
			nocache: true,
			showProcessing: false,
			defaultErrorHandling: true
		});
	}

	getDocumentType(userId, identityDocumentId) {
		return jsSubmit({
			action: `/webapi/users/${userId}/info/identityDocuments/identityDocumentType/${identityDocumentId}`,
			method: "GET",
			auth: true,
			showProcessing: false,
			defaultErrorHandling: true
		});
	}

	deleteDocument(userId, docId) {
		return jsSubmit({
			action: `/webapi/users/${userId}/info/identityDocuments/${docId}`,
			data: null,
			method: "DELETE",
			auth: true,
			nocache: true,
			showProcessing: true,
			defaultErrorHandling: true
		});
	}
}

module.exports = IdentityDocumentsCtrl;


