export class UserParamDependenciesManager {
	constructor() {
		this.dependencies = [];

		const deferred = $.Deferred();
		this.ready = deferred.promise();

		//загрузка всех зависимостей между полями ЛК
		const dependenciesReady = jsSubmit({
			action: "/webapi/users/paramDependecies",
			auth: false,
			data: {ver: appContext.version},
			method: "get"
		}).then((response) => {
			this.dependencies = response;
		});

		const manager = this;

		const controlUtils = new ControlUtils();

		//собираем все параметры с формы
		this.paramFields = new ParamsCollector().collect();

		//загружаем информацию о зависимостях параметров ЛК
		$.when(dependenciesReady).then(() => {

			const prepareAction = (paramInfo, actionInfo) => {
				if (actionInfo.actionType === DependActionType.Show) {
					if (paramInfo.groupItem) {
						return () => $(paramInfo.groupItem).show();
					} else {
						return () => $(paramInfo.formGroup).show();
					}
					
				}
				if (actionInfo.actionType === DependActionType.Hide) {
					if (paramInfo.groupItem) {
						return () => $(paramInfo.groupItem).hide();
					} else {
						return () => $(paramInfo.formGroup).hide();
					}
				}
				return () => {};
			}
		

			const getDependencyActions = (paramId, value) => {
				const dependentParams = _.filter(manager.dependencies, (dep) => {return dep.condition.param === paramId });
				if (!dependentParams.length) {
					return [];
				}

				if (value === "-1") {
					value = "";
				}

				let actions = [];

				for (let depInfo of dependentParams) {
					let dependParam = _.findWhere(manager.paramFields, { paramId: depInfo.dependParam });
					if (!dependParam) {
						//на форме нет зависимого параметра
						continue;
					}

					let actionInfo = null;
					if (depInfo.condition.operator === "Empty") {
						actionInfo = !value ? depInfo.then : depInfo.else;
					}
					if (depInfo.condition.operator === "NotEmpty") {
						actionInfo = value ? depInfo.then : depInfo.else;
					}
					if (depInfo.condition.operator === "Equals") {
						actionInfo = (value == depInfo.condition.value) ? depInfo.then : depInfo.else;
					}

					if (!actionInfo) {
						continue;
					}

					const action = prepareAction(dependParam, actionInfo);
					actions.push({ actionType: actionInfo.actionType, dependParam, action });
				}

				return actions;
			}
			
			for (let paramInfo of manager.paramFields) {
				const dependentParams = _.filter(manager.dependencies, (dep) => {return dep.condition.param === paramInfo.paramId });

				if (!dependentParams.length) {
					continue;
				}

				const value = $(paramInfo.control).val();

				$(paramInfo.control).data("prev-value", value);

				$(paramInfo.control).on("change", function() {
					const control = $(this);
					const setValue = control.val();
					const changeActions = getDependencyActions(paramInfo.paramId, setValue);

					const clearActions = _.filter(changeActions, (act) => act.actionType === DependActionType.Hide && !controlUtils.isEmpty(act.dependParam.control));

					_.each(clearActions, (act) => {
						//для действия скрытия добавляем также очистку
						const prevAction = act.action;
						act.action = () => {
							prevAction();
							controlUtils.clearVal(act.dependParam.control);
						}
					});

					if (!clearActions.length) {
						//если действия не критичные - то просто выполняем их и запоминаем установленное значение
						_.each(changeActions, (act) => act.action());
						control.data("prev-value", setValue);
						return;
					}

					//для действия - скрытия элемента дополнительно выводим подтверждение пользователю и только потом выполняем действия
					let confirmText = "После изменения станут недоступными и будут очищены следующие поля:";
					for (let hideAction of clearActions) {
						confirmText += "\n - " + hideAction.dependParam.label;
					}
					confirmText += "\n\n" + language.Generic.Common.kCfrmContinue;

					const yes = () => {
						_.each(changeActions, (act) => act.action());
						control.data("prev-value", setValue);
					};

					const no = () => {
						const prevValue = control.data("prev-value");
						control.val(prevValue);
					};
					$.show.confirmation(confirmText).then(yes, no);
				});

				//выполняем все правила при инициализации, без диалогов
				const paramDepActions = getDependencyActions(paramInfo.paramId, value);
				_.each(paramDepActions, (paramDepAction) => paramDepAction.action());
			}

			deferred.resolve();
		});
	}
}

class ParamsCollector {
	collect() {
		const paramRegexp = /^P_(\d+)_(\w)_(.+)$/;

		const paramFields = [];
		$("[name^='P_']", document.forms.UserInfo).each(function() {
			const control = this;
			const name = control.name;

			if (!name) {
				return;
			}

			const matches = name.match(paramRegexp);
			if (!matches || !matches.length) {
				return;
			}

			const formGroup = $(this).closest("div.form-group");
			const groupItem = $(this).closest("div.group-item");

			let label = null;
			if (groupItem.length) {
				label = groupItem.find("label").text();
			} else {
				label = formGroup.find("label").text();
			}

			paramFields.push({
				control: control,
				formGroup: formGroup.length ? formGroup[0] : null,
				groupItem : groupItem.length ? groupItem[0] : null,
				label: label,
				paramId: parseInt(matches[1])
			});

		});

		return paramFields;
	}
}

class ControlUtils {
	//очистка контрола
	clearVal (control) {
		if (control.tagName === "SELECT") {
			$(control).val(-1);
		} else {
			$(control).val("");
		}
		//todo. не работает очистка малтичойз параметров
	}

	isEmpty (control) {
		const val = $(control).val();
		if (control.tagName === "SELECT") {
			return !val || val === "-1";
		} else {
			return !val;
		}
	}
}

const DependActionType = {
	Hide: "Hide",
	Show: "Show",
	SetValue: "SetValue"
}


